using JobOrbit.Application.DTOs.AdminDashboard;using JobOrbit.Application.Interfaces;namespace JobOrbit.Application.Services;public sealed class AdminDashboardService(IAdminDashboardRepository repository):IAdminDashboardService{public Task<AdminDashboardStatsDto>StatsAsync(CancellationToken t=default)=>repository.StatsAsync(t);public Task<IReadOnlyList<AdminUserGrowthDto>>UserGrowthAsync(DateTime f,DateTime to,CancellationToken t=default)=>repository.UserGrowthAsync(f,to,t);public Task<AdminApplicationOverviewDto>ApplicationOverviewAsync(CancellationToken t=default)=>repository.ApplicationOverviewAsync(t);public Task<IReadOnlyList<AdminRecentActivityDto>>RecentActivityAsync(int l,CancellationToken t=default)=>repository.RecentActivityAsync(Math.Clamp(l,1,50),t);public Task<AdminSystemHealthDto>SystemHealthAsync(CancellationToken t=default)=>repository.SystemHealthAsync(t);}
